// Constants and arithmetic for the Building Eval Datasets page only (eval/dataset-*). Imports the golden-set size from
// presets/production.ts. The split by source, the intent × difficulty counts and the lifecycle numbers are chosen to
// teach (ILLUSTRATIVE); each total is checked here so a figure and the page cannot drift from 200.

import { DATASETS } from "./production";

/**
 * Where the 200 golden tickets come from. 120 sampled from 30 days of production logs, 50 written by support leads
 * for rare and risky cases, 30 generated by a model from the policy text and checked by a person.
 * 120 + 50 + 30 = 200.
 */
export const SOURCES = [
  { id: "logs", label: "Production logs", count: 120 },
  { id: "experts", label: "Expert-written", count: 50 },
  { id: "synthetic", label: "Synthetic", count: 30 },
] as const;
if (SOURCES.reduce((s, x) => s + x.count, 0) !== DATASETS.goldenSet) {
  throw new Error("production-datasets: sources no longer sum to the golden set");
}

export const INTENTS = [
  "Order status",
  "Delivery problem",
  "Account and login",
  "Product question",
  "Refund or return",
] as const;
export const LEVELS = ["Easy", "Medium", "Hard"] as const;

/**
 * Cases per intent (rows) and difficulty (columns).
 *   rows:    24+14+8 = 46, 14+16+10 = 40, 16+12+8 = 36, 20+14+10 = 44, 16+14+4 = 34 -> 200
 *   columns: 24+14+16+20+16 = 90 easy, 14+16+12+14+14 = 70 medium, 8+10+8+10+4 = 40 hard -> 200
 * The thin cell is refunds and returns, hard: 4 cases.
 */
export const GRID = [
  [24, 14, 8],
  [14, 16, 10],
  [16, 12, 8],
  [20, 14, 10],
  [16, 14, 4],
] as const;
export const THIN = { row: 4, col: 2 } as const;

export const rowTotals = GRID.map((r) => r.reduce((a, b) => a + b, 0));
export const colTotals = LEVELS.map((_, c) => GRID.reduce((a, r) => a + r[c], 0));
export const gridTotal = rowTotals.reduce((a, b) => a + b, 0);
if (gridTotal !== DATASETS.goldenSet) throw new Error("production-datasets: grid no longer sums to the golden set");

/** One wrong answer in the thin cell moves that cell's pass rate by 1 ÷ 4 = 25 points. */
export const thinCell = GRID[THIN.row][THIN.col];
export const thinStepPoints = 100 / thinCell;

/**
 * The 95 % confidence half-width of a pass rate p measured on n cases, normal approximation:
 *   1.96 × √(p (1 − p) / n), in percentage points.
 * p = 0.8: n = 50 -> 11.1, 100 -> 7.8, 200 -> 5.5, 400 -> 3.9, 800 -> 2.8. Reasonable when n p and n (1 − p) are both
 * at least about 10 (n >= 63 at p = 0.8); below that or near 0 % and 100 % use the Wilson interval.
 */
export const PASS_RATE = 0.8;
export const halfWidth = (n: number, p = PASS_RATE) => 100 * 1.96 * Math.sqrt((p * (1 - p)) / n);
export const f1 = (v: number) => v.toFixed(1);

/** Two annotators disagree on 22 of 200 cases: agreement (200 − 22) ÷ 200 = 89 %. */
export const ADJUDICATE = { disagreements: 22, agree: DATASETS.goldenSet - 22 } as const;
export const agreementPct = Math.round((100 * ADJUDICATE.agree) / DATASETS.goldenSet);
/** A monthly refresh retires 12 cases the policy changed and adds 12 from new failures: still 200. */
export const REFRESH = { retired: 12, added: 12 } as const;
